#### 2. Saga Orchestrator Implementation

```typescript
// src/domain/saga/booking-saga-orchestrator.ts

import type { BookingStepPort, StepResult } from "../ports/booking-step.port.js";

export type SagaState = "PENDING" | "COMPLETED" | "COMPENSATING" | "FAILED";

export interface SagaLog<T> {
  stepName: string;
  input: T;
  status: "EXECUTED" | "COMPENSATED";
}

export class BookingSagaOrchestrator {
  private readonly executedSteps: SagaLog<unknown>[] = [];

  async executeSaga<TInput>(
    steps: BookingStepPort<unknown, unknown>[],
    initialInput: TInput,
    traceId: string,
  ): Promise<SagaState> {
    for (const step of steps) {
      const res = await this.runStep(step, initialInput, traceId);
      if (!res.success) return this.rollback(steps, traceId);
    }
    return "COMPLETED";
  }

  private async runStep(
    step: BookingStepPort<unknown, unknown>,
    input: unknown,
    traceId: string,
  ): Promise<StepResult<unknown>> {
    const result = await step.execute(input, traceId);
    if (result.success) {
      this.executedSteps.push({ stepName: step.name, input, status: "EXECUTED" });
    }
    return result;
  }

  private async rollback(
    steps: BookingStepPort<unknown, unknown>[],
    traceId: string,
  ): Promise<SagaState> {
    const toRollback = [...this.executedSteps].reverse();
    for (const log of toRollback) {
      const step = steps.find((s) => s.name === log.stepName);
      if (step) await step.compensate(log.input, traceId);
    }
    return "FAILED";
  }
}
```

