#### 2. Concrete Discount Strategies (`src/domain/pricing/strategies.ts`)

```typescript
import type { CheckoutContext, DiscountResult, DiscountStrategy } from "./discount-strategy.js";

export class B2BTierDiscountStrategy implements DiscountStrategy {
  readonly name = "B2B Gold Tier Discount";

  isApplicable(context: CheckoutContext): boolean {
    return context.customerTier === "B2B_GOLD";
  }

  calculateDiscount(context: CheckoutContext): DiscountResult {
    const subtotal = calculateSubtotal(context.items);
    return { discountAmount: subtotal * 0.15, ruleName: this.name };
  }
}

export class CouponDiscountStrategy implements DiscountStrategy {
  readonly name = "Percentage Coupon Discount";

  isApplicable(context: CheckoutContext): boolean {
    return context.couponCode === "SUMMER20";
  }

  calculateDiscount(context: CheckoutContext): DiscountResult {
    const subtotal = calculateSubtotal(context.items);
    return { discountAmount: subtotal * 0.20, ruleName: this.name };
  }
}

function calculateSubtotal(items: readonly { price: number; quantity: number }[]): number {
  return items.reduce((acc, item) => acc + item.price * item.quantity, 0);
}
```

#### 3. Strategy Pipeline / Pricing Engine (`src/domain/pricing/pricing-engine.ts`)

```typescript
import type { CheckoutContext, DiscountStrategy } from "./discount-strategy.js";

export class PricingEngine {
  constructor(private readonly strategies: readonly DiscountStrategy[]) {}

  calculateTotalDiscount(context: CheckoutContext): number {
    return this.strategies
      .filter((strategy) => strategy.isApplicable(context))
      .reduce((acc, strategy) => acc + strategy.calculateDiscount(context).discountAmount, 0);
  }
}
```

#### 4. Decoupled Checkout Flow (`src/checkout.ts`)

```typescript
import type { CheckoutContext } from "./domain/pricing/discount-strategy.js";
import type { PricingEngine } from "./domain/pricing/pricing-engine.js";

export class CheckoutService {
  constructor(private readonly pricingEngine: PricingEngine) {}

  processCheckout(context: CheckoutContext): number {
    const subtotal = context.items.reduce((acc, item) => acc + item.price * item.quantity, 0);
    const discount = this.pricingEngine.calculateTotalDiscount(context);
    return Math.max(0, subtotal - discount);
  }
}
```

