### Step 1: Branch by Abstraction (Application Domain Boundary)

Introduce an abstraction layer in front of billing operations inside your application layer before making infrastructural routing changes. High-level policies depend on an interface port (`IBillingService`), isolating legacy SDKs and database schemas.

#### Strategy Pattern Adapter Implementation

```typescript
export interface BillingRequest {
  accountId: string;
  amountCents: number;
  currency: string;
  idempotencyKey: string;
}

export interface BillingResponse {
  transactionId: string;
  status: 'SUCCESS' | 'FAILED';
  timestamp: string;
}

export interface IBillingService {
  processPayment(request: BillingRequest): Promise<BillingResponse>;
}

export class RoutingBillingAdapter implements IBillingService {
  constructor(
    private readonly legacyService: IBillingService,
    private readonly newService: IBillingService,
    private readonly featureFlags: FeatureFlagClient,
    private readonly shadowQueue: ShadowExecutionQueue
  ) {}

  async processPayment(request: BillingRequest): Promise<BillingResponse> {
    const routeMode = await this.featureFlags.getRouteMode('process_payment', request.accountId);

    switch (routeMode) {
      case 'NEW':
        return this.executeWithFallback(request);

      case 'SHADOW':
        // Execute legacy live, shadow test new service asynchronously
        const legacyResult = await this.legacyService.processPayment(request);
        this.shadowQueue.enqueue(() => this.newService.processPayment(request), legacyResult);
        return legacyResult;

      case 'LEGACY':
      default:
        return this.legacyService.processPayment(request);
    }
  }

  private async executeWithFallback(request: BillingRequest): Promise<BillingResponse> {
    try {
      return await this.newService.processPayment(request);
    } catch (error) {
      // Instant fallback to legacy module on new service unexpected errors
      logger.error('New billing service failed, initiating instant fallback', { error, request });
      return await this.legacyService.processPayment(request);
    }
  }
}
```

