import { ShippingCarrierPort, RateRequest, ShippingRate } from '../ports/shipping-carrier.port';

export class FulfillmentService {
  constructor(private readonly carrierPort: ShippingCarrierPort) {}

  async getOptimalRate(request: RateRequest): Promise<ShippingRate> {
    const rates = await this.carrierPort.getRates(request);
