### 3. Pipeline Orchestrator ($v(G) = 1, LCOM4 = 1$)

Replace the multi-branch `switch/case` statement with a linear, strongly-typed pipeline:

```typescript
// src/domain/pipeline/pipeline-step.interface.ts
export interface OrderPipelineStep {
  name: string;
  execute(order: Order): Promise<Order>;
}

// src/application/order-processing-pipeline.ts
export class OrderProcessingPipeline {
  constructor(private readonly steps: readonly OrderPipelineStep[]) {}

  public async process(initialOrder: Order): Promise<Order> {
    let currentOrder = initialOrder;

    for (const step of this.steps) {
      currentOrder = await step.execute(currentOrder);
    }

    return currentOrder;
  }
}
```

