  customerId: string;
  status: 'STARTED' | 'FLIGHT_BOOKED' | 'HOTEL_RESERVED' | 'COMPLETED' | 'COMPENSATING' | 'FAILED';
  flightConfirmationId?: string;
  hotelConfirmationId?: string;
  failureReason?: string;
}

export interface FlightServicePort {
