#### Orchestrator Implementation (`src/infrastructure/saga/booking-saga.orchestrator.ts`)

```typescript
import { BookingSagaState, FlightServicePort, HotelServicePort } from '../../domain/ports/booking-saga.port';

export class BookingSagaOrchestrator {
  constructor(
    private readonly flightService: FlightServicePort,
    private readonly hotelService: HotelServicePort,
    private readonly sagaRepository: { save(state: BookingSagaState): Promise<void> }
  ) {}

  async executeBooking(sagaId: string, customerId: string, bookingDetails: any): Promise<BookingSagaState> {
    const state: BookingSagaState = {
      sagaId,
      customerId,
      status: 'STARTED',
    };
    await this.sagaRepository.save(state);

    // Step 1: Reserve Flight
    const flightResult = await this.flightService.reserveTicket(sagaId, bookingDetails.flight);
    if (!flightResult.success || !flightResult.data) {
      state.status = 'FAILED';
      state.failureReason = flightResult.errorMessage ?? 'Flight reservation failed';
      await this.sagaRepository.save(state);
      return state;
    }

    state.flightConfirmationId = flightResult.data.confirmationId;
    state.status = 'FLIGHT_BOOKED';
    await this.sagaRepository.save(state);

    // Step 2: Reserve Hotel
    const hotelResult = await this.hotelService.reserveRoom(sagaId, bookingDetails.hotel);
    if (!hotelResult.success || !hotelResult.data) {
      state.status = 'COMPENSATING';
      state.failureReason = hotelResult.errorMessage ?? 'Hotel reservation failed';
      await this.sagaRepository.save(state);

      // Automated Compensation Phase
      await this.compensate(state);
      return state;
    }

    state.hotelConfirmationId = hotelResult.data.confirmationId;
    state.status = 'COMPLETED';
    await this.sagaRepository.save(state);

    return state;
  }

  private async compensate(state: BookingSagaState): Promise<void> {
    if (state.flightConfirmationId) {
      const rollbackResult = await this.flightService.cancelTicket(state.sagaId, state.flightConfirmationId);
      if (!rollbackResult.success) {
        // Log critical metric for operator intervention trigger
        console.error(`CRITICAL: Compensation failed for saga ${state.sagaId}. Manual intervention required.`);
      }
    }
    state.status = 'FAILED';
    await this.sagaRepository.save(state);
  }
}
```

